import asyncio, os, sys, time
from run import run_tasks

MARK = "/tmp/_mark4.txt"
t0 = time.time()
def log(m):
    with open(MARK, "a") as f:
        f.write(f"{time.time()-t0:6.3f} {m}\n"); f.flush()

async def main():
    def mk(i):
        async def job():
            log(f"start {i}")
            try:
                await asyncio.sleep(10)
            finally:
                log(f"cleaned {i}")
        return job
    await run_tasks([mk(i) for i in range(3)], 2)

if __name__ == "__main__":
    if os.path.exists(MARK): os.remove(MARK)
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        log("KI in main")

